package org.whispersystems.libsignal.migration;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertTrue;

import org.junit.Test;
import org.whispersystems.libsignal.ecc.Curve;
import org.whispersystems.libsignal.ecc.ECKeyPair;

/**
 * Proves Curve25519 EC keys are byte-compatible across the vendored ({@code org.whispersystems})
 * and maintained ({@code org.signal}) libraries. This is the prerequisite for moving the local
 * at-rest crypto (AsymmetricMasterCipher, MasterCipher.encrypt/decryptKey, IdentityKeyUtil) off the
 * archived curve25519-java onto the maintained Rust {@code ecc} core: existing on-disk key blobs
 * (a 32-byte private scalar, a 33-byte {@code 0x05}-prefixed public point) must decode under the new
 * API and yield an identical ECDH agreement, or locked-state decryption would break for upgrading
 * users.
 */
public class EcKeyCrossLibraryTest {

  @Test
  public void ecKeysDecodeAndAgreeAcrossLibraries() throws Exception {
    ECKeyPair vendoredAlice = Curve.generateKeyPair();
    ECKeyPair vendoredBob   = Curve.generateKeyPair();

    byte[] alicePrivBytes = vendoredAlice.getPrivateKey().serialize();
    byte[] alicePubBytes  = vendoredAlice.getPublicKey().serialize();
    byte[] bobPrivBytes   = vendoredBob.getPrivateKey().serialize();
    byte[] bobPubBytes    = vendoredBob.getPublicKey().serialize();

    // The agreement the current (vendored) at-rest code computes.
    byte[] vendoredAgreement = Curve.calculateAgreement(vendoredBob.getPublicKey(),
                                                        vendoredAlice.getPrivateKey());

    // Decode the SAME serialized bytes under the maintained library.
    org.signal.libsignal.protocol.ecc.ECPrivateKey newAlicePriv =
        org.signal.libsignal.protocol.ecc.Curve.decodePrivatePoint(alicePrivBytes);
    org.signal.libsignal.protocol.ecc.ECPublicKey newBobPub =
        org.signal.libsignal.protocol.ecc.Curve.decodePoint(bobPubBytes, 0);

    // Re-serialization under the new library is byte-identical (on-disk blob survives round-trip).
    assertArrayEquals(alicePrivBytes, newAlicePriv.serialize());
    assertArrayEquals(bobPubBytes, newBobPub.serialize());

    // Maintained-library ECDH over the decoded keys equals the vendored agreement.
    byte[] newAgreement =
        org.signal.libsignal.protocol.ecc.Curve.calculateAgreement(newBobPub, newAlicePriv);
    assertArrayEquals(vendoredAgreement, newAgreement);

    // Reverse direction agrees too.
    org.signal.libsignal.protocol.ecc.ECPrivateKey newBobPriv =
        org.signal.libsignal.protocol.ecc.Curve.decodePrivatePoint(bobPrivBytes);
    org.signal.libsignal.protocol.ecc.ECPublicKey newAlicePub =
        org.signal.libsignal.protocol.ecc.Curve.decodePoint(alicePubBytes, 0);
    byte[] newAgreementReverse =
        org.signal.libsignal.protocol.ecc.Curve.calculateAgreement(newAlicePub, newBobPriv);
    assertArrayEquals(vendoredAgreement, newAgreementReverse);
  }

  /**
   * The vendored {@code ecc.Curve} now delegates XEd25519 signing/verification to the maintained Rust
   * core. This proves those signatures interoperate with the archived {@code curve25519-java} in both
   * directions, i.e. signatures we create are verifiable by peers on the previous build, and signatures
   * from such peers verify for us. (Signed-prekey signatures in the Key-Exchange path depend on this.)
   */
  @Test
  public void xed25519SignaturesInteroperateWithArchivedCurve() throws Exception {
    ECKeyPair pair    = Curve.generateKeyPair();        // vendored Curve == Rust engine now
    byte[]    message = "silence-signed-prekey".getBytes();

    byte[] pub33  = pair.getPublicKey().serialize();    // 0x05 || 32-byte point
    byte[] pub32  = java.util.Arrays.copyOfRange(pub33, 1, pub33.length);
    byte[] priv32 = pair.getPrivateKey().serialize();

    org.whispersystems.curve25519.Curve25519 archived =
        org.whispersystems.curve25519.Curve25519.getInstance(org.whispersystems.curve25519.Curve25519.BEST);

    // Rust-created signature verifies under the archived curve25519-java (peer on the previous build).
    byte[] rustSig = Curve.calculateSignature(pair.getPrivateKey(), message);
    assertTrue(archived.verifySignature(pub32, message, rustSig));

    // curve25519-java-created signature verifies under the Rust engine (message from such a peer).
    byte[] archivedSig = archived.calculateSignature(priv32, message);
    assertTrue(Curve.verifySignature(pair.getPublicKey(), message, archivedSig));
  }

  /**
   * Decisive cross-library agreement check using a key generated by the archived curve25519-java
   * itself (i.e. a properly clamped key, as all real keys are). The maintained Rust engine must
   * produce the identical X25519 shared secret — proving the engine swap preserves agreement for
   * real-world keys (peers on the previous build). Deliberately-unclamped hand-crafted vectors are a
   * separate matter and are not representative of any key produced in practice.
   */
  @Test
  public void x25519AgreementInteroperatesWithArchivedCurve() throws Exception {
    org.whispersystems.curve25519.Curve25519 archived =
        org.whispersystems.curve25519.Curve25519.getInstance(org.whispersystems.curve25519.Curve25519.BEST);

    org.whispersystems.curve25519.Curve25519KeyPair a = archived.generateKeyPair();
    org.whispersystems.curve25519.Curve25519KeyPair b = archived.generateKeyPair();

    byte[] archivedAgreement = archived.calculateAgreement(b.getPublicKey(), a.getPrivateKey());

    byte[] bPub33 = new byte[33];
    bPub33[0] = 0x05;
    System.arraycopy(b.getPublicKey(), 0, bPub33, 1, 32);

    org.signal.libsignal.protocol.ecc.ECPublicKey  bPub  = org.signal.libsignal.protocol.ecc.Curve.decodePoint(bPub33, 0);
    org.signal.libsignal.protocol.ecc.ECPrivateKey aPriv = org.signal.libsignal.protocol.ecc.Curve.decodePrivatePoint(a.getPrivateKey());
    byte[] rustAgreement = org.signal.libsignal.protocol.ecc.Curve.calculateAgreement(bPub, aPriv);

    assertArrayEquals(archivedAgreement, rustAgreement);
  }
}
